def get_config():
    return {"port": 8080, "retries": 3}

def read(name):
    with open(name) as f:
        return f.read()

# file: constants.py
DEFAULT_PORT = 8080
MAX_RETRIES = 3

===== CURRENT FILE PREFIX (server.py, truncated at target) =====
